-- SaMi Errands PostgreSQL schema; initialized on the isolated SaMi Errands Development project.
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),full_name text NOT NULL CHECK(length(trim(full_name)) BETWEEN 2 AND 120),email text NOT NULL,phone text,password_hash text NOT NULL,role text NOT NULL CHECK(role IN ('customer','provider','admin')),is_active boolean NOT NULL DEFAULT true,email_verified_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS users_email_lower_unique ON users(lower(email));
CREATE TABLE IF NOT EXISTS provider_profiles (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,provider_type text NOT NULL DEFAULT 'individual' CHECK(provider_type IN ('individual','business','team')),business_name text,service_categories text[] NOT NULL DEFAULT '{}',service_area text,bio text,approval_status text NOT NULL DEFAULT 'pending' CHECK(approval_status IN ('pending','approved','rejected','suspended')),available boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS errands (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),public_code text NOT NULL UNIQUE,customer_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,provider_id uuid REFERENCES users(id) ON DELETE SET NULL,title text NOT NULL CHECK(length(trim(title)) BETWEEN 3 AND 160),category text NOT NULL,description text NOT NULL CHECK(length(trim(description)) BETWEEN 5 AND 5000),pickup_location text,destination_location text,service_area text NOT NULL,due_at timestamptz,budget_amount numeric(12,2) CHECK(budget_amount IS NULL OR budget_amount>=0),quote_amount numeric(12,2) CHECK(quote_amount IS NULL OR quote_amount>=0),provider_payout numeric(12,2) CHECK(provider_payout IS NULL OR provider_payout>=0),currency char(3) NOT NULL DEFAULT 'KES',status text NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','quoted','assigned','accepted','in_progress','completion_submitted','completed','disputed','cancelled','declined')),payment_status text NOT NULL DEFAULT 'unpaid' CHECK(payment_status IN ('unpaid','pending','paid','refunded')),payment_method text,payment_reference text,completion_notes text,customer_confirmed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(provider_id IS NULL OR provider_id<>customer_id));
CREATE INDEX IF NOT EXISTS errands_customer_created_idx ON errands(customer_id,created_at DESC);
CREATE INDEX IF NOT EXISTS errands_provider_status_idx ON errands(provider_id,status,updated_at DESC);
CREATE INDEX IF NOT EXISTS errands_dispatch_idx ON errands(status,service_area,created_at ASC);
CREATE TABLE IF NOT EXISTS errand_events (id bigserial PRIMARY KEY,errand_id uuid NOT NULL REFERENCES errands(id) ON DELETE CASCADE,actor_id uuid REFERENCES users(id) ON DELETE SET NULL,event_type text NOT NULL,from_status text,to_status text,note text,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS errand_events_timeline_idx ON errand_events(errand_id,created_at ASC);
CREATE TABLE IF NOT EXISTS errand_messages (id bigserial PRIMARY KEY,errand_id uuid NOT NULL REFERENCES errands(id) ON DELETE CASCADE,sender_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,message text NOT NULL CHECK(length(trim(message)) BETWEEN 1 AND 4000),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS errand_messages_thread_idx ON errand_messages(errand_id,created_at ASC);
CREATE TABLE IF NOT EXISTS payment_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),errand_id uuid NOT NULL REFERENCES errands(id) ON DELETE RESTRICT,recorded_by uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,record_type text NOT NULL CHECK(record_type IN ('customer_payment','provider_payout','refund','adjustment')),amount numeric(12,2) NOT NULL CHECK(amount>=0),currency char(3) NOT NULL DEFAULT 'KES',method text NOT NULL,reference text,status text NOT NULL DEFAULT 'recorded' CHECK(status IN ('recorded','pending','reconciled','reversed')),notes text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS payment_records_errand_idx ON payment_records(errand_id,created_at DESC);
CREATE TABLE IF NOT EXISTS user_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),last_seen_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS user_sessions_user_expiry_idx ON user_sessions(user_id,expires_at);
CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY,applied_at timestamptz NOT NULL DEFAULT now());
INSERT INTO schema_migrations(version) VALUES('2026-10-25-sami-errands-initial') ON CONFLICT DO NOTHING;